function pfMulberry32(seed){
  var a = seed >>> 0;
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function pfBuildPool(opts){
  var lower='abcdefghijklmnopqrstuvwxyz';
  var upper='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var digit='0123456789';
  var sym='!@#$%^&*()-_=+[]{};:,.<>?';
  var pool='';
  if(opts.lower!==false) pool+=lower;
  if(opts.upper!==false) pool+=upper;
  if(opts.digit!==false) pool+=digit;
  if(opts.symbol) pool+=sym;
  if(opts.avoidAmbiguous) pool=pool.replace(/[Il1O0o]/g,'');
  if(pool==='') pool=lower+upper+digit;
  return pool;
}
function pfClasses(opts){
  var classes=[];
  if(opts.lower!==false) classes.push('abcdefghijklmnopqrstuvwxyz');
  if(opts.upper!==false) classes.push('ABCDEFGHIJKLMNOPQRSTUVWXYZ');
  if(opts.digit!==false) classes.push('0123456789');
  if(opts.symbol) classes.push('!@#$%^&*()-_=+[]{};:,.<>?');
  if(opts.avoidAmbiguous) classes=classes.map(function(c){return c.replace(/[Il1O0o]/g,'');});
  return classes;
}
function pfGenerate(opts){
  opts=opts||{};
  var length=opts.length||16;
  var rng=(typeof opts.rng==='function')?opts.rng:Math.random;
  var pool=pfBuildPool(opts);
  var poolArr=pool.split('');
  var requireAll=opts.requireAll!==false;
  var classes=pfClasses(opts);
  var out=[];
  var i;
  for(i=0;i<length;i++) out.push(poolArr[Math.floor(rng()*poolArr.length)]);
  if(requireAll && classes.length>0 && classes.length<=length){
    for(var c=0;c<classes.length;c++){
      var clsArr=classes[c].split('');
      out[c]=clsArr[Math.floor(rng()*clsArr.length)];
    }
    for(var i2=length-1;i2>0;i2--){
      var j=Math.floor(rng()*(i2+1));
      var t=out[i2]; out[i2]=out[j]; out[j]=t;
    }
  }
  var pw=out.join('');
  var entropy=length*(Math.log(pool.length)/Math.log(2));
  return {password:pw, length:length, poolSize:pool.length, entropyBits:entropy, charset:pool};
}
